# -*- coding: utf-8 -*-
"""برومبتات الصور القصصية للوحدة U09 (يولّدها صاحب المشروع). يكتب:
art-sources/U09/prompts/prompts-final-imagegen.json و art-sources/U09/prompts/الصور-القصصية-للنسخ.md
الاستعمال: python3 art-sources/U09/sources/prompts_u09.py
"""
from pathlib import Path
import json

HERE = Path(__file__).resolve().parent
OUT = HERE.parent / 'prompts'
STYLE = ("Warm children's picture-book illustration, soft rounded cartoon style for ages 8–12, thick clean outlines, flat colors with gentle soft shading, "
         "cheerful warm palette (cream background #FFF6E3, coral #FF6B57, teal #2BB3A3, sunny yellow #FFC93C, sky blue #BFE7FF), friendly expressive faces with big round eyes, "
         "Egyptian/Arab children, modest everyday clothes, no text, no letters, no logos, no watermark, high resolution, consistent character design. Vertical portrait image, 1024×1536.")
BOY = "the hero boy (match the attached reference exactly: short dark curly hair, warm brown skin, light-blue t-shirt, dark-blue jeans, blue sneakers)"
GIRL = "the hero girl (match the attached reference exactly: dark hair in two braids, warm brown skin, pink long-sleeved top, dark-blue jeans, pink sneakers)"
LAM = "Lammah (match the attached reference: a living magnifying glass with a sky-blue lens face, golden rim, a short wooden handle as its body, thin arms with white cartoon gloves, short legs with teal sneakers)"
END = " No text, no letters, no numbers anywhere in the image."
NEG = "text, letters, numbers, captions, labels, watermark, logos, realistic photo, horror, creepy, extra fingers, deformed hands, anatomically wrong organs, genitals, toilet, blood, gore, dark background, needles pointing at faces, weapons, soldiers, crosses, religious symbols"
RB, RG, RL = 'مرجع-البطل-ولد.png', 'مرجع-البطلة-بنت.png', 'مرجع-لماح.png'

SKIN_WIN = ("A big round see-through window beside the child shows a close-up slice of skin like a layered cake: a thin top layer of flat tile-like cells flaking off at the surface "
            "with plump round cells just below them, then a thicker pink layer with tiny red blood vessels, a thin yellow nerve thread, a coiled sweat-gland tube and one hair with its root, "
            "and a soft pale-yellow fat layer at the bottom.")
def title(kid, who):
    return {
      'L01': f"Title scene for a lesson about the skin as a living shield that renews itself. {kid} sits on a park bench smiling and looking at a small clean bandage on {who} knee (a healed scrape, no blood). {SKIN_WIN} {LAM} holds the round window like a lens. MUST: two clear skin layers above a fat layer; the top cells flat and flaking, the cells under them round; children of every skin tone are equally beautiful — no comparison; no blood.",
      'L02': f"Title scene for a lesson about body heat. The picture is split down the middle. Left half: a sunny summer afternoon, {kid} rests in the shade of a tree with rosy cheeks and tiny sweat drops on the forehead, drinking from a water bottle. Right half: a cold windy winter day, the same child wears a warm jacket and scarf, the skin of the hand is pale with tiny goosebumps and small shiver lines around the body. Over the head a soft see-through window shows a small glowing spot at the base of the brain like a tiny round dial with a pointer in the middle (no numbers, no marks). {LAM} stands at the dividing line holding a small fan in one hand and a wool hat in the other. MUST: hot side rosy and sweaty, cold side pale with goosebumps; the dial has no numbers or letters.",
      'L03': f"Title scene for a lesson about how the body keeps germs out. {kid} washes both hands at a sink with lots of white soap foam, smiling, scrubbing between the fingers. Around the hands, tiny cute cartoon germ blobs (green and purple, silly faces, not scary) slide away down the drain with the bubbles. A small round see-through window on one fingertip shows a tiny splinter with a little pink area around it, where round friendly white blob-cells hug and swallow tiny germ blobs. {LAM} holds a bar of soap like a trophy. MUST: germs are tiny and silly, not monsters; white cells are soft round blobs, NOT soldiers, no weapons, no armor; running water from a tap.",
      'L04': f"Title scene for a lesson about vaccines and protecting others. {kid} stands proudly with a tiny round skin-colored bandage on {who} upper arm, holding hands with a grandmother in a modest dress and a soft headscarf; a baby cousin sleeps in a stroller beside them. A soft glowing translucent bubble of light surrounds the whole family, and outside it a few tiny cute germ blobs bounce off the bubble. {LAM} gives a thumbs-up. MUST: no syringe or needle anywhere; only a tiny round bandage on the arm; the bubble is light, not a weapon or shield with symbols.",
    }

def items():
    P = []
    def add(name, refs, prompt, check, lesson=None):
        P.append({'name': name, 'lesson': lesson or name[:7], 'refs': refs, 'prompt': STYLE + '\n\n' + prompt + END, 'negative': NEG, 'check': check})
    tb, tg = title(BOY, 'his'), title(GIRL, 'her')
    chk_title = {
      'L01': 'نافذة مقطع الجلد: طبقتان فوق طبقة دهن، الخلايا العليا مسطحة تتقشر وتحتها مستديرة؛ في الطبقة الوردية وعاء أحمر وعصب أصفر وغدة عرق ملتفة وشعرة بجذرها؛ الركبة بضمادة بلا دم.',
      'L02': 'نصف حار (خدود وردية وقطرات عرق في الظل) ونصف بارد (جلد شاحب وقشعريرة وارتجاف)؛ القرص في قاع الدماغ بلا أرقام ولا علامات.',
      'L03': 'الميكروبات كائنات صغيرة مضحكة لا وحوش؛ الخلايا البيضاء كرات لطيفة بلا أسلحة ولا دروع؛ رغوة الصابون بين الأصابع.',
      'L04': 'لا حقنة ولا إبرة في الصورة كلها؛ ضمادة صغيرة مستديرة على أعلى الذراع؛ الفقاعة ضوء شفاف بلا رموز.',
    }
    for L in ['L01', 'L02', 'L03', 'L04']:
        add(f'U09.{L}-title-boy.webp', [RB, RL], tb[L], chk_title[L])
        add(f'U09.{L}-title-girl.webp', [RG, RL], tg[L], 'كما في غلاف الولد.')
    # ———— U09.L01 ————
    add('U09.L01-exp.webp', [RB, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) Two similar shiny red apples on two plates side by side on a table. (2) A grown-up's hand gently scratches three or four thin lines into the peel of the second apple with a wooden toothpick (no knife), while {BOY} watches. (3) A few days later: the scratched apple has soft brown patches around the scratches, while the untouched apple is still shiny and red. (4) A notebook with an empty table of blank boxes and a pencil. {LAM} holds a small calendar with blank squares in a corner. MUST: no knife; the brown soft patches only around the scratches; the table is empty; the calendar has no numbers.", 'لا سكين (عود أسنان بيد الكبير)؛ البقع البنية حول الخدوش فقط والتفاحة السليمة لامعة؛ الجدول والتقويم بلا أرقام.')
    add('U09.L01-letter.webp', [RL], f"Letter scene: a cute rounded character that is a small square slice of layered skin — a thin peach top layer, a pink middle layer with one tiny red vessel and one thin yellow nerve, and a soft pale-yellow bottom layer — with a big friendly face on the pink layer and small arms. It sits at a little wooden desk writing a letter with a feather pen; the letter shows only wavy lines. Beside the desk: a wide-brimmed sun hat, a clean bandage and a small bar of soap. {LAM} reads over its shoulder. MUST: the character clearly shows the layers; the letter has only wavy lines, no writing.", 'الشخصية شريحة جلد بطبقاتها؛ الرسالة خطوط متموجة بلا كتابة؛ القبعة والضمادة والصابون بجانبها.')
    add('U09.L01-life.webp', [RB, RL], f"Everyday-life scene on a school trip by the sea: {BOY} and a new classmate with darker brown skin sit together under a big beach umbrella, both wearing wide-brimmed hats and light long-sleeved shirts; the boy offers his friend a water bottle and they laugh together. In the background other children of many skin tones build a sandcastle in the shade. {LAM} adjusts its own tiny hat. MUST: children of different skin tones shown equally happy, friendly and beautiful; nobody is sunburned; no swimwear close-ups.", 'أطفال بألوان بشرة مختلفة سعداء متساوون؛ قبعات ومظلة وظل؛ لا حرق شمس ظاهر.')
    add('U09.L01-hist1.webp', [RL], f"Historical scene in Córdoba, al-Andalus, around the year 1000: a kind physician with a short dark beard, a white turban and a long robe sits at a wooden table in a bright room with a horseshoe-arch window, carefully drawing surgical instruments — slender scalpels, hooks, forceps, a curved needle with thread — on a large sheet of paper; the real instruments lie neatly on a white cloth beside the paper, with rolls of cotton bandage and small spools of thread. {LAM} holds a spool of thread. MUST: the paper shows only drawings of instruments, no writing; no patient, no blood; the physician is a gentle cartoon figure, not a portrait; no religious symbols.", 'رسوم أدوات فقط بلا كتابة؛ لا مريض ولا دم؛ نافذة بقوس أندلسي؛ لا رموز دينية.')
    # ———— U09.L02 ————
    add('U09.L02-exp.webp', [RG, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) {GIRL} has a damp folded cloth on the back of her right hand and a dry folded cloth on the back of her left hand. (2) She fans both hands with a folded paper fan. (3) She touches her cheek with the back of the right hand and makes a happy 'so cool!' face with a few tiny snowflake-like sparkles near the hand. (4) Two small digital thermometers lie on a table, one wrapped in a wet tissue and one in a dry tissue, their small screens blank, and a notebook with an empty table of blank boxes. {LAM} fans them with a paper fan. MUST: thermometer screens are blank; no mercury or glass thermometers; water is plain room-temperature water.", 'شاشات الموازين فارغة بلا أرقام؛ لا ميزان زجاجي؛ القماش المبلل على اليمنى والجاف على اليسرى.')
    add('U09.L02-letter.webp', [RL], f"Letter scene: inside a soft pink layer of skin live a family of tiny cute coiled-tube characters (sweat glands), each like a small curly noodle with a friendly face; their tubes rise to the skin surface where tiny water droplets float up and turn into soft steam swirls in the air. The biggest one holds a letter with only wavy lines and a little water bottle. {LAM} waves from the surface above. MUST: the glands are coiled tubes inside the skin with ducts reaching the surface; droplets evaporate into soft swirls; no writing.", 'غدد العرق أنابيب ملتفة داخل الجلد لها قنوات إلى السطح؛ قطرات تتبخر؛ الرسالة بلا كتابة.')
    add('U09.L02-life.webp', [RG, RL], f"Everyday-life scene on a hot sunny school playground at noon: {GIRL} has stopped a football game and helps her friend (another girl in a modest long-sleeved top) sit down in the shade of a wall; the friend looks tired and a little dizzy (a small swirl above her head) and holds a water bottle the hero girl gave her; the hero girl waves to a grown-up teacher hurrying over. A soccer ball rests nearby. {LAM} holds a small umbrella over the friend. MUST: the friend sits safely in the shade; no vomit, no fainting on the ground; calm and caring mood.", 'الصديقة جالسة في الظل وتشرب؛ لا قيء ولا سقوط؛ المعلم قادم.')
    add('U09.L02-hist1.webp', [RL], f"Historical scene in a German hospital ward around 1860: a doctor with a neat beard and a dark frock coat gently holds a long glass thermometer under the arm of a resting patient sitting up in bed; rows of neat iron beds and tall windows; a nurse in a long dress and apron writes in a huge ledger book full of tiny wavy lines and simple wavy graph curves. {LAM} peeks from behind the ledger. MUST: the thermometer has small tick marks only, no digits; the ledger shows wavy lines and curves, no writing or numbers; the patient is calm and comfortable; no crosses or religious symbols.", 'الميزان بعلامات بلا أرقام؛ السجل خطوط ومنحنيات بلا كتابة؛ لا رموز دينية.')
    # ———— U09.L03 ————
    add('U09.L03-exp.webp', [RB, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) {BOY} rubs his palms with a little cooking oil while a grown-up sprinkles brown cinnamon powder on them from a small jar. (2) He rinses his hands under running water only, without soap: lots of brown powder is still stuck, especially between the fingers and under the nails. (3) He washes with soap and thick foam, scrubbing the backs of the hands, between the fingers and under the nails. (4) Clean hands, a towel, and a notebook with an empty table of blank boxes. {LAM} holds a little sand-timer. MUST: the powder stays mostly between fingers and under nails after water only; hands far from eyes; no glitter; the sand-timer has no numbers.", 'بعد الماء وحده تبقى القرفة بين الأصابع وتحت الأظفار؛ بعد الصابون تزول؛ اليدان بعيدتان عن العين؛ لا أرقام.')
    add('U09.L03-letter.webp', [RL], f"Letter scene inside a blood vessel: a round, soft, friendly white blob-cell character with a gentle face floats in a stream of red disc-shaped red blood cells; it holds a letter with only wavy lines in one small arm and, with its soft body, is gently hugging and swallowing a tiny silly green germ blob. {LAM} floats in a tiny submarine bubble nearby. MUST: the white cell is a soft round blob, NOT a soldier, no weapons, no armor, no helmet; red blood cells are red discs with a dimple; no writing.", 'الخلية البيضاء كرة لطيفة بلا سلاح ولا خوذة؛ الكريات الحمراء أقراص حمراء؛ الرسالة بلا كتابة.')
    add('U09.L03-life.webp', [RB, RL], f"Everyday-life scene at school before lunch: {BOY} and his friend stand at a row of sinks; the friend wanted to just splash water quickly, but the boy shows him how to lather soap and scrub between the fingers and under the nails, and both are laughing while counting with a little song (music notes in the air); lunch boxes wait on a table behind them. {LAM} hands out paper towels. MUST: thick soap foam on both boys' hands; running tap water; music notes only, no text.", 'رغوة صابون كثيفة؛ فرك بين الأصابع؛ نوتات موسيقية بلا كتابة.')
    add('U09.L03-hist1.webp', [RL], f"Historical scene in a large hospital in Vienna in 1847: a young doctor with dark side whiskers and a 19th-century dark coat washes his hands carefully in a white porcelain basin of clear water; behind him, a few other doctors in dark coats watch with doubtful, raised-eyebrow faces and folded arms; tall arched windows and a long corridor. {LAM} holds a towel for the young doctor. MUST: no patients, no bodies, no autopsy, no blood; no crosses or religious symbols; gentle cartoon figures, not portraits.", 'طبيب يغسل يديه وزملاء متشككون؛ لا مرضى ولا تشريح ولا دم؛ لا صلبان.')
    # ———— U09.L04 ————
    add('U09.L04-exp.webp', [RG, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) A large sheet of paper on a table with a big ring of twenty small empty circles drawn on it. (2) {GIRL} places red beans on one circle, then on its two neighbors, then spreads them all around the ring until every circle has a red bean. (3) A second round: most circles have blue beans; the red beans start at one circle and stop at the first blue bean on each side; one circle in the middle of a group of blue circles stays empty and safe. (4) A notebook with an empty table of blank boxes. {LAM} points at the safe empty circle. MUST: twenty circles in a ring; red stops at blue; nobody puts beans in their mouth; no text.", 'حلقة من عشرين دائرة؛ الأحمر يتوقف عند الأزرق؛ دائرة فارغة آمنة وسط الزرقاء؛ بلا كتابة.')
    add('U09.L04-letter.webp', [RL], f"Letter scene: a round, soft, friendly white blob-cell character wearing small round glasses sits in a cozy armchair turning the pages of a photo album full of silly cartoon portraits of different germ blobs (like a family album of 'faces I remember'); it holds a letter with only wavy lines. On a little side table: a tiny round bandage and a small toy shield made of light. {LAM} looks at the album with it. MUST: no syringes or needles; germs in the album are silly, not scary; no writing.", 'ألبوم صور لميكروبات مضحكة؛ لا حقن ولا إبر؛ الرسالة بلا كتابة.')
    add('U09.L04-life.webp', [RG, RL], f"Everyday-life scene in a home kitchen: a grandmother in a modest dress and a soft headscarf holds the back of her hand under cool running water from the kitchen tap; {GIRL} stands close, gently supporting her elbow and looking at a simple kitchen clock on the wall, while calling to a grown-up who is coming in through the door. A tea cup lies tipped over on the counter with a small puddle. {LAM} holds a clean plastic food wrap roll. MUST: the burn is only a light pink patch, no blisters, no blood; no butter or toothpaste anywhere; the clock has no numbers (just dots).", 'الحرق بقعة وردية خفيفة بلا فقاعات؛ ماء الصنبور الجاري؛ لا زبدة ولا معجون؛ الساعة بلا أرقام.')
    add('U09.L04-hist1.webp', [RL], f"Historical scene in a hospital in Baghdad around the year 900: a wise physician with a grey beard and a turban sits on a low cushion beside a sick child resting on a mattress in a bright room with arches and a small fountain; the physician observes the child's face carefully (a few small reddish spots on the cheeks, not scary) and writes in a book with a reed pen; a helper brings a cup of water. {LAM} holds an oil lamp. MUST: only a few small spots, the child calm and comfortable; the book shows only wavy lines; no religious symbols; gentle cartoon figures, not portraits.", 'بقع صغيرة قليلة غير مخيفة؛ الطفل مرتاح؛ الكتاب خطوط بلا كتابة؛ لا رموز دينية.')
    add('U09.L04-hist2.webp', [RL], f"Historical scene in the English countryside in May 1796: a kind country doctor in an 18th-century coat and a short white wig sits on a wooden chair in a sunny garden and gently holds the bare upper arm of a calm eight-year-old boy sitting on a stool; on the boy's arm there is only a tiny dot; behind them a milkmaid in a bonnet stands beside a friendly brown-and-white cow at a wooden fence. {LAM} hands the doctor a small clean cloth. MUST: no blood, no needle or blade visible, no sores on the cow or the milkmaid; the boy is calm.", 'لا دم ولا إبرة ولا مشرط ظاهر؛ نقطة صغيرة على الذراع؛ لا قروح ظاهرة على البقرة أو الحلّابة.')
    add('U09.L04-E5.webp', [RB, RL], f"Everyday-life scene in a bright classroom: {BOY} and several classmates warmly welcome a classmate who has just come back to school after being ill for two weeks; the boy hands him a notebook with the lessons he missed, another child pulls out a chair for him, and the smiling teacher waves from the front. {LAM} carries a little stack of books. MUST: everyone is kind and smiling, nobody points or steps away; the board and the notebook show only wavy lines, no writing.", 'الجميع لطفاء مرحّبون؛ لا أحد يشير أو يبتعد؛ السبورة والدفتر بلا كتابة.')
    return P

if __name__ == '__main__':
    P = items()
    OUT.mkdir(parents=True, exist_ok=True)
    data = {'unit': 'U09', 'style': STYLE, 'negative': NEG,
            'pending_imagegen': {p['name']: {k: p[k] for k in ('lesson', 'refs', 'prompt', 'negative', 'check')} for p in P}}
    (OUT / 'prompts-final-imagegen.json').write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    TT = {'title-boy': 'غلاف (ولد)', 'title-girl': 'غلاف (بنت)', 'exp': 'التجربة', 'letter': 'الرسالة', 'life': 'في حياتي', 'hist1': 'علماء 1', 'hist2': 'علماء 2', 'E5': 'مشهد الشرح E5'}
    md = ['# برومبتات الصور القصصية — الوحدة U09 «الجلد والدفاع والحرارة واللقاحات» (%d صورة)' % len(P), '',
          '**طريقة العمل:**',
          '1. لكل صورة: أرفق في أداة التوليد صور المرجع المذكورة (مرجع البطل والبطلة ولمّاح، كما في U07 وU08)، ثم الصق البرومبت كما هو؛ فيه وصف الأسلوب الموحّد في أوله.',
          '2. المقاس عمودي **1024×1536**. بلا أي كتابة أو أرقام داخل الصورة.',
          '3. احفظ كل صورة **بالاسم المكتوب فوقها بالضبط** (WebP أو PNG، وأنا أحوّل)، ثم أرسلها مضغوطة في ملف واحد أو أرفقها هنا.',
          '4. قبل أن تقبل الصورة، راجع سطر «تحقق» تحتها.', '',
          f'**Negative prompt (إن كانت الأداة تقبله):** `{NEG}`', '']
    for i, p in enumerate(P, 1):
        slot = p['name'].split('-', 1)[1].replace('.webp', '')
        md += [f"## {i}. `{p['name']}` — {p['lesson']} {TT.get(slot, slot)}", f"**أرفق:** {'، '.join(p['refs'])}", '', '```', p['prompt'], '```', f"**تحقق:** {p['check']}", '']
    (OUT / 'الصور-القصصية-للنسخ.md').write_text('\n'.join(md), encoding='utf-8')
    print(len(P), 'برومبت')
